/**
 * Algorithm Hypothesis engine tests.
 *
 * golden.entity_binding.json is generated by the `algorithm_hypothesis` Python
 * package (python -m algorithm_hypothesis.golden), which compiles each algorithm
 * to causalab. Matching it cell for cell keeps this engine and causalab in
 * agreement. Copy the file over when the Python side changes.
 */

import { describe, it, expect } from "bun:test";
import type { AlgorithmDefinition } from "@/types/algorithmHypothesis";
import golden from "./golden.entity_binding.json";
import {
    evaluate,
    fullSweep,
    type PythonResolver,
    inferTypes,
    interchangeIntervention,
    moveProblem,
    outputOf,
    parseAlgorithmFile,
    problems,
    removeVariable,
    tokenSweep,
    upgradeDefinition,
    withSpecialTokens,
    type SweepStatus,
} from "../engine";
import {
    PRIMITIVES,
    errorValue,
    isError,
    primitiveAsPython,
    primitiveSource,
    show,
    tokenValue,
} from "../primitives";
import { PRIMITIVE_SOURCES } from "../primitiveSources";
import runtimeBundle from "../pythonRuntime.json";
import { describeType } from "../vartypes";
import { entityBindingExample, EXAMPLE_KINDS, nameTokens, type ExampleKind } from "../presets";
import { tokenizeAbstract } from "../grids";

type Golden = {
    prompts: Record<string, string>;
    primitives: Record<
        string,
        {
            label: string;
            slots: { name: string; type: unknown }[];
            returns: unknown;
            options: { name: string; default: unknown; choices: string[] | null }[];
            source: string;
        }
    >;
    tokens: Record<string, string[]>;
    algorithms: Record<string, AlgorithmDefinition>;
    base_outputs: Record<string, string>;
    sweeps: {
        algorithm: string;
        source: string;
        token: number;
        rows: { layer: number; output: string; status: SweepStatus }[];
    }[];
    full: { algorithm: string; source: string; outputs: string[][]; status: SweepStatus[][] }[];
};

const G = golden as unknown as Golden;
const TARGET = G.tokens.target;
const SOURCE = G.tokens.source;
const LAST = TARGET.length - 1;
const example = (kind: ExampleKind) =>
    entityBindingExample(
        kind,
        TARGET,
        { kind: "abstract", layers: 8 },
        G.prompts.target,
    ) as AlgorithmDefinition;

describe("golden file (generated by the Python package)", () => {
    it("has the same primitives, signatures and Python sources", () => {
        expect(Object.keys(PRIMITIVES).sort()).toEqual(Object.keys(G.primitives).sort());
        for (const [name, p] of Object.entries(G.primitives)) {
            const ts = PRIMITIVES[name as keyof typeof PRIMITIVES];
            expect(ts.label).toBe(p.label);
            expect(ts.slots).toEqual(p.slots as typeof ts.slots);
            expect(ts.returns).toEqual(p.returns as typeof ts.returns);
            expect(
                ts.options.map((o) => ({
                    name: o.name,
                    default: o.default,
                    choices: o.choices ?? null,
                })),
            ).toEqual(p.options as never);
            expect(PRIMITIVE_SOURCES[name as keyof typeof PRIMITIVE_SOURCES]).toBe(p.source);
        }
    });

    it("tokenizes prompts the same way", () => {
        for (const [k, text] of Object.entries(G.prompts))
            expect(tokenizeAbstract(text)).toEqual(G.tokens[k]);
    });

    it("builds the same example algorithms", () => {
        for (const [name, alg] of Object.entries(G.algorithms)) {
            const [kind, layers] = name.split("_");
            const built = entityBindingExample(
                kind as ExampleKind,
                TARGET,
                { kind: "abstract", layers: Number(layers) },
                G.prompts.target,
            );
            expect(built).toEqual(alg);
        }
    });

    it("computes the same target outputs", () => {
        for (const [name, alg] of Object.entries(G.algorithms))
            expect(show(outputOf(alg, evaluate(alg, TARGET)))).toBe(G.base_outputs[name]);
    });

    it("matches every token sweep", () => {
        for (const s of G.sweeps) {
            const rows = tokenSweep(
                G.algorithms[s.algorithm],
                G.tokens[s.source],
                TARGET,
                s.token,
                s.token,
            );
            expect(
                rows.map((r) => ({ layer: r.layer, output: show(r.output), status: r.status })),
            ).toEqual(s.rows);
        }
    });

    it("matches every full sweep cell for cell", () => {
        for (const f of G.full) {
            const cols = fullSweep(G.algorithms[f.algorithm], G.tokens[f.source], TARGET);
            expect(cols.map((c) => c.map((r) => show(r.output)))).toEqual(f.outputs);
            expect(cols.map((c) => c.map((r) => r.status))).toEqual(f.status);
        }
    });
});

describe("the paper's predictions", () => {
    it("each algorithm predicts its own entity in the binding window", () => {
        const expected: Record<ExampleKind, string> = {
            positional: "jam",
            lexical: "ale",
            reflexive: "pie",
            // One answer per mechanism, combined with equal weights.
            mixed: "jam / ale / pie",
        };
        for (const kind of EXAMPLE_KINDS) {
            const r = interchangeIntervention(
                example(kind),
                SOURCE,
                TARGET,
                { layer: 5, token: LAST },
                { layer: 5, token: LAST },
            );
            expect(r.ok).toBe(true);
            expect(show(r.output)).toBe(expected[kind]);
        }
    });

    it("only swaps variables with the same name", () => {
        const r = interchangeIntervention(
            example("positional"),
            SOURCE,
            TARGET,
            { layer: 3, token: 18 },
            { layer: 5, token: LAST },
        );
        expect(r.ok).toBe(false);
        expect(r.reason).toContain("same name");
        expect(show(r.output)).toBe("tea");
    });
});

describe("editing", () => {
    const alg = entityBindingExample(
        "positional",
        TARGET,
        { kind: "abstract", layers: 8 },
        G.prompts.target,
    ) as AlgorithmDefinition;

    it("the example has no problems", () => {
        expect(problems(alg, TARGET.length)).toEqual([]);
    });

    it("infers types", () => {
        const { types, problems: typeProblems } = inferTypes(alg);
        expect(describeType(types.get("pos1"))).toBe("position : string");
        expect(describeType(types.get("id1"))).toBe("position");
        expect(describeType(types.get("bind1"))).toBe("position : string");
        expect(describeType(types.get("q_pos"))).toBe("position : string");
        expect(describeType(types.get("P"))).toBe("position");
        expect(describeType(types.get("answer"))).toBe("string");
        expect(typeProblems.size).toBe(0);
    });

    it("reports arguments of the wrong type", () => {
        const bad: AlgorithmDefinition = {
            ...alg,
            variables: alg.variables.map((v) =>
                v.id === "answer"
                    ? { ...v, args: [{ name: "key", refs: [{ token: 0 }] }, v.args[1]] }
                    : v,
            ),
        };
        expect(problems(bad, TARGET.length).map((p) => p.message)).toContain(
            "pairs: bind1 is position : string, but this argument needs string : any type (V).",
        );
    });

    it("moves keep the algorithm autoregressive", () => {
        // P reads q_pos (L3) and is read by answer (L7); q_pos reads the names up to token 18.
        expect(moveProblem(alg, "P", { layer: 4, token: LAST }, TARGET.length)).toBeNull();
        expect(moveProblem(alg, "P", { layer: 3, token: LAST }, TARGET.length)).toContain(
            "lower layer",
        );
        expect(moveProblem(alg, "P", { layer: 7, token: LAST }, TARGET.length)).toContain(
            "must stay below",
        );
        expect(moveProblem(alg, "q_pos", { layer: 3, token: 12 }, TARGET.length)).toContain(
            "causal mask",
        );
        expect(moveProblem(alg, "answer", { layer: 6, token: LAST }, TARGET.length)).toContain(
            "output",
        );
    });

    it("removing a variable removes references to it", () => {
        const next = removeVariable(alg, "P");
        expect(next.variables.find((v) => v.id === "P")).toBeUndefined();
        const answer = next.variables.find((v) => v.id === "answer")!;
        expect(answer.args.find((a) => a.name === "key")!.refs).toEqual([]);
        expect(show(outputOf(next, evaluate(next, TARGET)))).toBe("∅");
        expect(
            problems(next, TARGET.length).some((p) => p.message.includes("exactly one reference")),
        ).toBe(true);
    });

    const withPython: AlgorithmDefinition = {
        ...alg,
        variables: alg.variables.map((v) =>
            v.id === "P"
                ? {
                      ...v,
                      type: { kind: "position" },
                      function: {
                          kind: "python",
                          source: "def compute(pair):\n    return pair.key\n",
                      },
                  }
                : v,
        ),
    };

    it("python variables are pending until a resolver answers", () => {
        expect(show(outputOf(withPython, evaluate(withPython, TARGET)))).toBe("…");
        const pending: PythonResolver = () => ({ kind: "pending" });
        expect(show(outputOf(withPython, evaluate(withPython, TARGET, { python: pending })))).toBe(
            "…",
        );
    });

    it("python variables take the resolver's value, in interventions too", () => {
        const calls: unknown[] = [];
        // Stands in for the worker: compute(pair) returns pair.key.
        const identity: PythonResolver = (v, args) => {
            calls.push(args);
            return (args.pair as { key: number }).key;
        };
        expect(show(outputOf(withPython, evaluate(withPython, TARGET, { python: identity })))).toBe(
            "tea",
        );
        expect(calls).toEqual([
            { pair: { kind: "pair", key: 4, value: { kind: "token", text: "Tim", index: 18 } } },
        ]);
        const r = interchangeIntervention(
            withPython,
            SOURCE,
            TARGET,
            { layer: 5, token: LAST },
            { layer: 5, token: LAST },
            { python: identity },
        );
        expect(show(r.output)).toBe("jam");
    });

    it("a python error shows in place and names itself downstream", () => {
        const failing: PythonResolver = () =>
            errorValue("ZeroDivisionError: division by zero (line 2)");
        const ev = evaluate(withPython, TARGET, { python: failing });
        expect(isError(ev.values.P)).toBe(true);
        const answer = ev.values.answer;
        expect(isError(answer) && answer.message).toBe("Depends on P, which failed.");
    });
});

describe("color and tags", () => {
    it("the examples are colored by the algorithm each variable serves", () => {
        const color = (kind: ExampleKind) =>
            new Map(example(kind).variables.map((x) => [x.id, x.color ?? null]));
        const mixed = color("mixed");
        expect(
            ["q_pos", "P", "pos_answer", "L", "lex_answer", "R", "ref_answer"].map((id) =>
                mixed.get(id),
            ),
        ).toEqual(["indigo", "indigo", "indigo", "emerald", "emerald", "amber", "amber"]);
        expect([mixed.get("pos_bind1"), mixed.get("bind1"), mixed.get("answer")]).toEqual([
            "indigo",
            null,
            null,
        ]);
        expect(example("mixed").variables.find((x) => x.id === "bind1")!.tags).toEqual([
            "lexical",
            "reflexive",
        ]);
        // Alone, each algorithm colors what only it uses; the shared bindings stay black.
        const black = (kind: ExampleKind) =>
            [...color(kind)].filter(([, c]) => !c).map(([id]) => id);
        expect(black("positional")).toEqual([]);
        expect(black("lexical")).toEqual(["bind1", "bind2", "bind3", "bind4"]);
        expect(black("reflexive")).toEqual(["bind1", "bind2", "bind3", "bind4"]);
        expect(color("lexical").get("answer")).toBe("emerald");
    });
});

describe("python runtime bundle (generated by the Python package)", () => {
    it("ships the runtime and the same primitive sources, without causalab", () => {
        const files = runtimeBundle.files as Record<string, string>;
        expect(Object.keys(files).sort()).toEqual(
            ["__init__.py", "primitives.py", "runtime.py", "values.py", "vartypes.py"].sort(),
        );
        expect(files["runtime.py"]).toContain("def call_batch(");
        for (const source of Object.values(PRIMITIVE_SOURCES))
            expect(files["primitives.py"]).toContain(source.trim());
        for (const text of Object.values(files))
            expect(text).not.toMatch(/^\s*(from|import)\s+causalab/m);
    });
});

describe("python sources", () => {
    it("bakes option values into the source", () => {
        expect(primitiveSource("retrieve", { match: "value" })).toContain('match: str = "value"');
        expect(primitiveSource("mixture", { weights: "2, 1" })).toContain('weights: str = "2, 1"');
        expect(primitiveAsPython("retrieve").startsWith("def compute(key")).toBe(true);
    });
});

describe("older schemas", () => {
    it("v1 upgrades: pointer becomes copy, glyphs go, types are inferred", () => {
        const v1 = {
            schema: "algorithm-hypothesis/v1",
            name: "Old",
            description: "",
            grid: { kind: "abstract", layers: 8 },
            template: G.prompts.target,
            output: "answer",
            variables: [
                {
                    id: "ptr1",
                    name: "ptr1",
                    cell: { layer: 2, token: 2 },
                    function: { kind: "primitive", name: "pointer", options: {} },
                    args: [{ name: "token", refs: [{ token: 2 }] }],
                    glyph: "pointer",
                },
            ],
        };
        const up = upgradeDefinition(v1);
        expect(up.schema).toBe("algorithm-hypothesis/v4");
        expect(up.variables[0].function).toEqual({ kind: "primitive", name: "copy", options: {} });
        expect(up.variables[0].args).toEqual([{ name: "x", refs: [{ token: 2 }] }]);
        expect(up.variables[0].type).toEqual({ kind: "string" });
        expect("glyph" in up.variables[0]).toBe(false);
    });

    it("v2 upgrades: removed primitives become custom functions with their old source", () => {
        const v = (id: string, name: string, args: unknown[], type: unknown, options = {}) => ({
            id,
            name: id,
            cell: { layer: 1, token: 2 },
            type,
            function: { kind: "primitive", name, options },
            args,
        });
        const v2 = {
            schema: "algorithm-hypothesis/v2",
            name: "Old",
            description: "",
            grid: { kind: "abstract", layers: 8 },
            template: G.prompts.target,
            output: null,
            variables: [
                v(
                    "p",
                    "position_id",
                    [{ name: "token", refs: [{ token: 0 }] }],
                    { kind: "position" },
                    { by: "token", delimiter: "," },
                ),
                v("k", "identity", [{ name: "token", refs: [{ token: 0 }] }], { kind: "string" }),
                v("l", "lookup", [{ name: "key", refs: [{ token: 0 }] }], { kind: "string" }),
            ],
        };
        const [p, k, l] = upgradeDefinition(v2).variables;
        expect(p.function.kind).toBe("python");
        expect(p.function.kind === "python" && p.function.source).toContain('by="token"');
        expect(p.function.kind === "python" && p.function.source).toContain("template=()");
        expect(p.type).toEqual({ kind: "position" });
        expect(k.function).toEqual({ kind: "primitive", name: "copy", options: {} });
        expect(l.function.kind === "python" && l.function.source).toContain(
            "def compute(key, keys, values)",
        );
    });
});

describe("schema v3", () => {
    it("upgrades the Eq. 2 Mixture to a custom function and keeps the rest", () => {
        const old = example("positional");
        const eq2 = {
            id: "mix",
            name: "mix",
            cell: { layer: 6, token: LAST },
            type: { kind: "string" },
            function: {
                kind: "primitive",
                name: "mixture",
                options: { w_pos: 3, sigma: 0.7, w_lex: 2.6, w_ref: 2.6 },
            },
            args: [
                { name: "P", refs: [{ variable: "P" }] },
                { name: "L", refs: [] },
                { name: "R", refs: [] },
                { name: "bindings", refs: [1, 2, 3, 4].map((k) => ({ variable: `bind${k}` })) },
            ],
        };
        const up = upgradeDefinition({
            ...old,
            schema: "algorithm-hypothesis/v3",
            variables: [...old.variables, eq2],
        });
        expect(up.schema).toBe("algorithm-hypothesis/v4");
        expect(up.variables.slice(0, -1)).toEqual(old.variables);
        const mix = up.variables.at(-1)!;
        expect(mix.function.kind === "python" && mix.function.source).toContain(
            "def compute(P, L, R, bindings, *, w_pos=3.0, sigma=0.7, w_lex=2.6, w_ref=2.6):",
        );
        expect(mix.type).toEqual({ kind: "string" });
    });
});

describe("mixture", () => {
    it("combines answers linearly; equal answers add up", () => {
        const ale = tokenValue("ale", 2);
        const run = (weights: string) =>
            PRIMITIVES.mixture.run({ answers: [ale, "jam", ale] }, { weights });
        expect(run("2, 1")).toEqual({
            kind: "distribution",
            items: [
                { label: "ale", p: 0.75 },
                { label: "jam", p: 0.25 },
            ],
        });
        expect(show(run(""))).toBe("ale");
        expect(isError(run("2, x"))).toBe(true);
    });

    it("the default special tokens are the prompt's names", () => {
        expect(nameTokens(TARGET)).toEqual([0, 4, 8, 12, 18]);
        expect(nameTokens(tokenizeAbstract("The cat sat on the mat."))).toEqual([]);
    });
});

describe("opening a file", () => {
    it("reads what Download writes, and says what's wrong with anything else", () => {
        const alg = entityBindingExample(
            "reflexive",
            TARGET,
            { kind: "abstract", layers: 8 },
            G.prompts.target,
        ) as AlgorithmDefinition;
        expect(parseAlgorithmFile(JSON.stringify(alg, null, 2))).toEqual(alg);

        const { name: _name, ...unnamed } = alg;
        void _name;
        expect(parseAlgorithmFile(JSON.stringify(unnamed)).name).toBe("Imported algorithm");

        const error = (text: string) => {
            try {
                parseAlgorithmFile(text);
                return null;
            } catch (e) {
                return (e as Error).message;
            }
        };
        expect(error("{")).toBe("It isn't valid JSON.");
        expect(error("[]")).toBe("It isn't an algorithm saved with Download.");
        expect(error(JSON.stringify({ ...alg, schema: "algorithm-hypothesis/v9" }))).toContain(
            "newer",
        );
        expect(error(JSON.stringify({ ...alg, grid: { kind: "abstract" } }))).toContain("grid");
        const broken = { ...alg, variables: [...alg.variables, { id: "x", name: "x" }] };
        expect(error(JSON.stringify(broken))).toBe(
            `Variable ${alg.variables.length + 1} is malformed.`,
        );
    });
});

describe("position IDs and dereferencing", () => {
    const run = (name: "position_id" | "retrieve", args: Record<string, unknown>, options = {}) =>
        PRIMITIVES[name].run(args as never, options);
    const tok = (text: string, index: number) => ({ kind: "token" as const, text, index });

    it("number the special tokens by first appearance and store ID : token", () => {
        const names = [
            tok("Joe", 0),
            tok("Ann", 4),
            tok("Pete", 8),
            tok("Tim", 12),
            tok("Ann's", 18),
        ];
        expect(show(run("position_id", { token: names[1], specials: names.slice(0, 2) }))).toBe(
            "2:Ann",
        );
        // A repeated name gets its first mention's ID; the possessive is ignored.
        expect(show(run("position_id", { token: names[4], specials: names }))).toBe("2:Ann's");
        expect(run("position_id", { token: tok("ale", 2), specials: names })).toBeNull();
    });

    it("the examples designate the names as special tokens", () => {
        const alg = entityBindingExample(
            "positional",
            TARGET,
            { kind: "abstract", layers: 8 },
            G.prompts.target,
        ) as AlgorithmDefinition;
        expect(alg.specialTokens).toEqual([0, 4, 8, 12, 18]);
        expect(show(evaluate(alg, TARGET).values.q_pos)).toBe("4:Tim");
        expect(show(evaluate(alg, SOURCE).values.q_pos)).toBe("2:Ann");
    });

    it("retrieve by value dereferences, finding nothing outside the context", () => {
        const binds = [
            { kind: "pair", key: tok("Ann", 0), value: tok("ale", 2) },
            { kind: "pair", key: tok("Joe", 4), value: tok("jam", 6) },
        ];
        expect(
            show(run("retrieve", { key: tok("jam", 9), pairs: binds }, { match: "value" })),
        ).toBe("jam");
        expect(
            run("retrieve", { key: tok("cod", 9), pairs: binds }, { match: "value" }),
        ).toBeNull();
        expect(run("retrieve", { key: tok("jam", 9), pairs: binds }, { match: "key" })).toBeNull();
    });
});

describe("special tokens", () => {
    it("every Position ID reads the special tokens up to its cell", () => {
        const alg = entityBindingExample(
            "positional",
            TARGET,
            { kind: "abstract", layers: 8 },
            G.prompts.target,
        ) as AlgorithmDefinition;
        // Drop Joe (4): Pete becomes the 2nd name and Tim the 3rd.
        const next = withSpecialTokens(alg, [0, 8, 12, 18]);
        const qPos = next.variables.find((v) => v.id === "q_pos")!;
        expect(qPos.args.find((a) => a.name === "specials")!.refs).toEqual([
            { token: 0 },
            { token: 8 },
            { token: 12 },
            { token: 18 },
        ]);
        const ev = evaluate(next, TARGET);
        expect(show(ev.values.q_pos)).toBe("3:Tim");
        expect(show(ev.values.pos2)).toBe("∅");
        expect(withSpecialTokens(alg, []).specialTokens).toBeUndefined();
    });
});
